// ambient modules can't import relative modules, their types are from the modules owning them

/** values of the build for the runtime, generated by the integration */
declare module 'virtual:fumadocs/config' {
  /** by collection, for `pageLoader()` and `metaLoader()` */
  export const loaders: Record<
    string,
    Pick<import('./index').CollectionConfig, 'dir' | 'extractLinkReferences' | 'lastModified'>
  >;
  /** the root directory of the project */
  export const root: string;
}
